# syntax=docker/dockerfile:1
# Development shell: docker build --target development -t stm:dev .
# Production image:  docker build -t stm:prod .

ARG UBUNTU_VERSION=26.04
# Optional exact Debian package version, shared by development and production.
ARG FLUENT_BIT_VERSION=""

FROM ubuntu:${UBUNTU_VERSION} AS development

ARG DEBIAN_FRONTEND=noninteractive
ARG FLUENT_BIT_VERSION

RUN apt-get update \
    && apt-get install --yes --no-install-recommends \
        build-essential \
        ca-certificates \
        cmake \
        curl \
        git \
        gpg \
        iproute2 \
        libsrt-openssl-dev \
        logrotate \
        nodejs \
        npm \
        python3 \
        python3-saneyaml \
        srt-tools \
        supervisor \
        tshark \
        tzdata \
        vim \
        wireshark-common \
    && rm -rf /var/lib/apt/lists/*

# Install the official package; process startup is managed separately by STM.
RUN curl -fsSL https://packages.fluentbit.io/fluentbit.key -o /tmp/fluentbit.key \
    && gpg --batch --yes --dearmor -o /usr/share/keyrings/fluentbit-keyring.gpg /tmp/fluentbit.key \
    && chmod 0644 /usr/share/keyrings/fluentbit-keyring.gpg \
    && . /etc/os-release \
    && printf 'deb [signed-by=/usr/share/keyrings/fluentbit-keyring.gpg] https://packages.fluentbit.io/ubuntu/%s %s main\n' \
        "${VERSION_CODENAME:?}" "${VERSION_CODENAME:?}" > /etc/apt/sources.list.d/fluent-bit.list \
    && apt-get update \
    && apt-get install --yes --no-install-recommends "fluent-bit${FLUENT_BIT_VERSION:+=$FLUENT_BIT_VERSION}" \
    && rm -f /tmp/fluentbit.key \
    && rm -rf /var/lib/apt/lists/*

WORKDIR /workspace
COPY . /workspace

# This stage is intentionally usable as a development environment.  Mount the
# checkout over /workspace when iterating locally.
CMD ["/bin/bash"]

FROM development AS builder
ARG STM_BUILD_COMMIT=""
ARG STM_BUILD_TIME=""
ENV STM_BUILD_COMMIT=${STM_BUILD_COMMIT} STM_BUILD_TIME=${STM_BUILD_TIME}
RUN python3 scripts/stm-build-information --output scripts/build-information.json

RUN cmake -S be/src -B be/build-release -DCMAKE_BUILD_TYPE=Release \
    && cmake --build be/build-release \
    && ctest --test-dir be/build-release --output-on-failure \
    && cmake --install be/build-release --prefix /opt/stm

WORKDIR /workspace/fe
RUN npm ci \
    && npm run build \
    && npm prune --omit=dev

FROM ubuntu:${UBUNTU_VERSION} AS production

ARG DEBIAN_FRONTEND=noninteractive
ARG FLUENT_BIT_VERSION

RUN apt-get update \
    && apt-get install --yes --no-install-recommends \
        ca-certificates \
        curl \
        gpg \
        logrotate \
        nodejs \
        python3 \
        supervisor \
        tshark \
        tzdata \
        wireshark-common \
    && groupadd --gid 10001 stm \
    && useradd --uid 10001 --gid stm --create-home --home-dir /nonexistent --shell /usr/sbin/nologin stm \
    && mkdir -p /opt/stm/bin /opt/stm/fe /opt/stm/default-conf /var/lib/stm/fe /var/lib/stm/supervisor /etc/stm \
    && install -d -m 0750 /var/log/stm \
    && install -d -m 0700 /run/stm \
    && chown -R stm:stm /opt/stm/fe /opt/stm/default-conf /var/lib/stm/fe /etc/stm \
    && rm -rf /var/lib/apt/lists/*

# Keep the repository and package selection identical to the development stage.
RUN curl -fsSL https://packages.fluentbit.io/fluentbit.key -o /tmp/fluentbit.key \
    && gpg --batch --yes --dearmor -o /usr/share/keyrings/fluentbit-keyring.gpg /tmp/fluentbit.key \
    && chmod 0644 /usr/share/keyrings/fluentbit-keyring.gpg \
    && . /etc/os-release \
    && printf 'deb [signed-by=/usr/share/keyrings/fluentbit-keyring.gpg] https://packages.fluentbit.io/ubuntu/%s %s main\n' \
        "${VERSION_CODENAME:?}" "${VERSION_CODENAME:?}" > /etc/apt/sources.list.d/fluent-bit.list \
    && apt-get update \
    && apt-get install --yes --no-install-recommends "fluent-bit${FLUENT_BIT_VERSION:+=$FLUENT_BIT_VERSION}" \
    && rm -f /tmp/fluentbit.key \
    && rm -rf /var/lib/apt/lists/*

COPY --from=builder /opt/stm/bin/ /opt/stm/bin/
COPY --from=builder /workspace/fe/node_modules/ /opt/stm/fe/node_modules/
COPY --from=builder /workspace/fe/server/dist/ /opt/stm/fe/server/dist/
COPY --from=builder /workspace/fe/client/dist/ /opt/stm/fe/client/dist/
COPY --from=builder /workspace/fe/server/package.json /opt/stm/fe/server/package.json
COPY --from=builder /workspace/fe/client/package.json /opt/stm/fe/client/package.json
COPY --from=builder /workspace/fe/package.json /opt/stm/fe/package.json
COPY --from=builder /workspace/fe/maintenance-settings.json /opt/stm/fe/maintenance-settings.json
COPY --from=builder /workspace/fe/locales/ /opt/stm/fe/locales/
COPY --from=builder /workspace/fe/external-pages/ /opt/stm/fe/external-pages/
COPY --from=builder /workspace/scripts/build-information.json /opt/stm/bin/build-information.json
COPY scripts/stm_version.py /opt/stm/bin/stm_version.py
COPY scripts/stm_notifications.py /opt/stm/bin/stm_notifications.py
COPY --chmod=755 scripts/stm-notifier scripts/stm-fluent-bit /opt/stm/bin/
COPY --chmod=755 scripts/stm-information /opt/stm/bin/
COPY --chown=stm:stm conf/ /opt/stm/default-conf/
COPY --chmod=755 scripts/stm-log-manager scripts/stm-log-level scripts/stm-capture-guard scripts/stm-process-stats scripts/stm-storage-manager scripts/stm-collect-logs /opt/stm/bin/
COPY --chmod=755 docker/entrypoint.sh /usr/local/bin/stm-entrypoint
COPY --chmod=755 docker/healthcheck.sh /usr/local/bin/stm-healthcheck
COPY docker/supervisord.conf /etc/supervisor/stm.conf

ENV STM_BIN_DIR=/opt/stm/bin \
    STM_CONFIG_DIR=/etc/stm \
    STM_FE_DIR=/opt/stm/fe \
    STM_DATA_DIR=/var/lib/stm \
    STM_LOG_DIR=/var/log/stm \
    STM_LOG_LEVEL_FILE=/run/stm/log-levels.json \
    STM_FRONTEND_USER=stm \
    STM_DEFAULT_CONFIG_DIR=/opt/stm/default-conf

EXPOSE 3000
VOLUME ["/etc/stm", "/var/lib/stm", "/var/log/stm"]

HEALTHCHECK --interval=30s --timeout=5s --start-period=30s --retries=3 CMD ["/usr/local/bin/stm-healthcheck"]

ENTRYPOINT ["/usr/local/bin/stm-entrypoint"]
CMD ["/usr/bin/supervisord", "-c", "/etc/supervisor/stm.conf"]
