import { copyFile, mkdir, rm } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import path from "node:path";

const execute = promisify(execFile);
type Options = { rootDir: string; file: string; stateDir: string; logDir: string; stmConfigFile?: string; signal?: AbortSignal };

// Production uses its entrypoint. A source checkout also needs this preparation
// for both `node dist/index.js` and `tsx watch`, regardless of the launch cwd.
export async function prepareDevelopmentInformation(options: Options, environment: NodeJS.ProcessEnv = process.env): Promise<boolean> {
  options.signal?.throwIfAborted();
  const project = path.resolve(options.rootDir, "..");
  const generator = path.join(project, "scripts/stm-information");
  const release = path.join(project, "conf/information.release.json");
  const defaultSupervisor = path.join(project, "docker/supervisord.dev.conf");
  if (environment.STM_INFORMATION_FILE !== undefined || ![generator, release, defaultSupervisor].every(file => existsSync(file))) return false;

  const supervisor = environment.SUPERVISOR_CONFIG
    ? path.resolve(project, environment.SUPERVISOR_CONFIG) : defaultSupervisor;
  const configDir = environment.STM_CONFIG_DIR ?? (options.stmConfigFile ? path.dirname(options.stmConfigFile) : path.join(project, "conf"));
  const env = {
    ...environment,
    PYTHONDONTWRITEBYTECODE: "1",
    STM_BIN_DIR: environment.STM_BIN_DIR ?? path.join(project, "be/build"),
    STM_CONFIG_DIR: configDir,
    STM_FE_DIR: environment.STM_FE_DIR ?? options.rootDir,
    STM_DATA_DIR: environment.STM_DATA_DIR ?? options.logDir,
    STM_LOG_DIR: environment.STM_LOG_DIR ?? path.join(options.stateDir, "logs"),
    STM_LOG_LEVEL_FILE: environment.STM_LOG_LEVEL_FILE ?? path.join(options.stateDir, "log-levels.json"),
    STM_FRONTEND_USER: environment.STM_FRONTEND_USER ?? environment.USER ?? "root"
  };
  try {
    // Source-mode startup may not have run the server packaging step yet.
    // Prepare display assets without replacing any program's build metadata.
    const styles = path.join(options.rootDir, "external-pages/assets");
    await mkdir(styles, { recursive: true });
    await Promise.all(["tokens.css", "base.css"].map(name => copyFile(path.join(options.rootDir, "client/src/styles", name), path.join(styles, name))));
    const { packageLicenses } = require(path.join(options.rootDir, "server/package-information.cjs")) as { packageLicenses(root: string): void };
    packageLicenses(project);
    await execute("python3", [generator, "--supervisor-config", supervisor,
      "--release", release, "--fe-dir", options.rootDir, "--output", options.file],
    { cwd: project, env, signal: options.signal, timeout: 60_000, maxBuffer: 256 * 1024 });
    return true;
  } catch (error) {
    // A previous deployment's inventory must not mask a failed generation.
    await rm(options.file, { force: true }).catch(() => undefined);
    throw error;
  }
}
