const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs/promises');
const path=require('node:path');
const repo='/var/work/repo3/stm/stm';
const {clientBrowser}=require(repo+'/fe/tests/helpers/client-browser.cjs');
const Fastify=require(repo+'/fe/node_modules/fastify');
const fastifyStatic=require(repo+'/fe/node_modules/@fastify/static');

test('Help renders both original decks continuously inside the application frame, resizes and handles a missing document',async t=>{
  const app=Fastify();let missing=false;
  app.addHook('onRequest',async(req,reply)=>{
    if(missing&&req.url.endsWith('SubmaLink-general-network.html'))return reply.code(404).send('missing');
  });
  await app.register(fastifyStatic,{root:path.join(repo,'fe/external-pages'),prefix:'/external-pages/'});
  app.get('/help-fixture',async(req,reply)=>reply.type('text/html').send('<html data-theme="dark"><body style="margin:0"><iframe id="help" src="/external-pages/help/" style="display:block;width:100%;height:100vh;border:0"></iframe></body></html>'));
  await app.listen({host:'127.0.0.1',port:0});t.after(()=>app.close());
  const b=await clientBrowser(t,'void 0;');if(!b)return;
  await b.call('Page.enable');
  const url=`http://127.0.0.1:${app.server.address().port}/help-fixture`;
  await b.call('Emulation.setDeviceMetricsOverride',{width:1280,height:900,deviceScaleFactor:1,mobile:false});
  await b.call('Page.navigate',{url});
  const d='document.getElementById("help").contentDocument';
  await b.wait(`${d}?.querySelectorAll('iframe.is-ready').length===2`);
  await b.wait(`[...${d}.querySelectorAll('iframe')].every(f=>[...f.contentDocument.images].every(i=>i.complete&&i.naturalWidth>0))`);
  assert.deepEqual(await b.evaluate(`[...${d}.querySelectorAll('iframe')].map(f=>f.contentDocument.querySelectorAll('.slide').length)`),[13,8]);
  assert.equal(await b.evaluate(`${d}.documentElement.dataset.theme`),'dark');
  assert.deepEqual(await b.evaluate(`[...${d}.querySelectorAll('iframe')].map(f=>f.contentDocument.body.className)`),['','']);
  const report=[];
  for(const width of [1280,600,375]){
    await b.call('Emulation.setDeviceMetricsOverride',{width,height:900,deviceScaleFactor:1,mobile:false});
    await b.wait(`[...${d}.querySelectorAll('iframe')].every(f=>Math.abs(f.getBoundingClientRect().height-f.contentDocument.body.getBoundingClientRect().height)<2)`);
    const layout=await b.evaluate(`(()=>{const d=${d};return {width:d.documentElement.clientWidth,scrollWidth:d.documentElement.scrollWidth,frames:[...d.querySelectorAll('iframe')].map(f=>{const c=f.contentDocument,slides=[...c.querySelectorAll('.slide')],r=slides[slides.length-1].getBoundingClientRect();return {width:f.clientWidth,height:f.clientHeight,firstWidth:slides[0].getBoundingClientRect().width,lastBottom:r.bottom,documentWidth:c.documentElement.scrollWidth}})}})()`);
    assert.ok(layout.scrollWidth<=layout.width+1,JSON.stringify(layout));
    for(const f of layout.frames){assert.ok(f.firstWidth<=f.width+1,JSON.stringify(f));assert.ok(f.lastBottom<=f.height+1,JSON.stringify(f));assert.ok(f.documentWidth<=f.width+1,JSON.stringify(f));}
    report.push(layout);
  }
  await b.call('Emulation.setDeviceMetricsOverride',{width:1280,height:900,deviceScaleFactor:1,mobile:false});
  await b.evaluate(`document.documentElement.dataset.theme='light'`);
  await b.wait(`${d}.documentElement.dataset.theme==='light'`);
  await b.evaluate(`${d}.defaultView.scrollTo(0,0)`);
  let shot=await b.call('Page.captureScreenshot');await fs.writeFile('/tmp/stm-help-desktop.png',Buffer.from(shot.data,'base64'));
  await b.evaluate(`${d}.querySelector('nav a[href="#general-network"]').click()`);
  await b.wait(`Math.abs(${d}.getElementById('general-network').getBoundingClientRect().top-16)<2`);
  shot=await b.call('Page.captureScreenshot');await fs.writeFile('/tmp/stm-help-second.png',Buffer.from(shot.data,'base64'));
  for(const link of await b.evaluate(`[...${d}.querySelectorAll('.section-heading a')].map(a=>({href:a.href,target:a.target}))`)){
    assert.equal(link.target,'_blank');const response=await fetch(link.href);assert.equal(response.status,200);assert.match(await response.text(),/id="navigation"/);
  }
  const hash=await b.evaluate(`${d}.defaultView.location.hash`);assert.equal(hash,'#general-network');
  missing=true;
  await b.call('Page.navigate',{url});
  await b.wait(`${d}?.querySelectorAll('.status.is-error').length===1`);
  assert.equal(await b.evaluate(`${d}.querySelectorAll('iframe.is-ready').length`),1);
  assert.match(await b.evaluate(`${d}.querySelector('.is-error').textContent`),/別タブで開く/);
  assert.deepEqual(b.errors,[]);
  console.log(JSON.stringify(report));
});

