#!/usr/bin/env python3
"""Build the 8-slide general network deck from the consolidated Markdown.

Reuses the connection-patterns deck's Chromium renderer and PowerPoint exporter.
Requires markdown, python-pptx, Pillow, pypdf, Node.js, the repository's ws,
Chromium, and a local Mermaid 11.4.1 mermaid.min.js bundle.

Example:
  PYTHONPATH=/tmp/submalink-slides-tools/python python3 build.py \
    --mermaid-js /tmp/submalink-slides-tools/mermaid.min.js
"""
import argparse
import base64
import hashlib
import html
import importlib.util
import json
from pathlib import Path
import re
import subprocess
import tempfile

import markdown

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
