.pattern-details .detail.compact p{font-size:19px;line-height:1.55}
.forms{position:absolute;top:150px;left:64px;right:64px;display:grid;grid-template-columns:repeat(3,1fr);gap:24px;height:175px}
.forms .panel{padding:22px 24px}.forms h3{font-size:24px;margin-bottom:12px}
.forms p{font-size:22px;line-height:1.6;margin:0}
.common.mapping{position:absolute;top:355px;left:64px;width:1472px;margin:0;font-size:21px}
