.common.checks th:first-child{width:280px}.common.checks td{padding:10px 18px}
.warning{font-size:22px}
'''


def split_sections(text, level=2):
    parts = re.split(r'^' + '#' * level + r' (.+)\n', text, flags=re.M)
    return dict(zip(parts[1::2], parts[2::2]))


def make_draft(source, logo_bytes, mermaid_js, work):
    text = source.read_text()
    sections = split_sections(text)
    patterns = [h for h in sections if re.match(r'^[1-3]\. ', h)]
    assert len(patterns) == 3
    logo = 'data:image/png;base64,' + base64.b64encode(logo_bytes).decode()
    inline_logo = f'<img class="brand-inline" src="{logo}" alt="SubmaLink">'
    def md(value):
        result = markdown.markdown(value, extensions=['tables'])
        result = re.sub(r'<img\b[^>]*alt="SubmaLink"[^>]*>', lambda m: inline_logo, result)
        return result.replace('<strong>SubmaLink</strong>', inline_logo)
    def cells_table(value, cls):
        return md(value).replace('<table>', f'<table class="{cls}">')
    def bullets(value):
        return ''.join('<p data-text>・' + md(line[2:]).removeprefix('<p>').removesuffix('</p>') + '</p>'
                       for line in value.splitlines() if line.startswith('- '))
    def plain_notes(raw):
        return re.sub(r'<img\b[^>]*alt="SubmaLink"[^>]*>', 'SubmaLink', raw)

    sources, notes, headings, slides = [], [], [], []
    def add(name, body, raw, kind=''):
        n = len(slides) + 1
        header = '' if kind == 'cover' else f'<p class="eyebrow" data-text>GENERAL NETWORK</p><h2 data-text>{html.escape(name)}</h2><img class="header-logo" src="{logo}" alt="SubmaLink">'
        slides.append(f'''<section class="slide {kind}" id="slide-{n}" aria-label="{html.escape(name)}"><div class="topline" data-shape></div>{header}{body}
<footer class="footer"><span data-text>一般的なネットワーク通信の監視</span><span data-text>{n:02d} / 08</span></footer></section>''')
        headings.append(name); notes.append(plain_notes(raw))

    add(TITLE, f'''<img class="cover-mark" src="{logo}" alt="SubmaLink">
<h1 data-text><img src="{logo}" alt="SubmaLink">活用事例：<br>一般的なネットワーク通信の監視</h1>
<p class="lead" data-text>通信相手の数と配置で、監視の構成を整理する。<br>8つの業務事例を、3つの基本パターンへ。</p>
<div class="tags"><span class="tag" data-shape data-text>個別通信</span><span class="tag" data-shape data-text>複数相手との通信</span><span class="tag" data-shape data-text>ホスト内通信</span></div>''', text.split('## 図の読み方')[0], 'cover')

    guide = sections['図の読み方']
    guide_bullets = '\n'.join([
        '- 実線は通信経路。双方向の矢印は送受信を表す。',
        '- ホスト枠内のNICが、取得対象のインターフェースとなる。',
        '- NICから**SubmaLink**への破線は観測の関係。業務データを監視プロセス経由で転送しない。',
        '- 取得対象NIC・権限・選別条件・ネットワーク名前空間を確認する。',
        '- ホスト内通信は、ループバック上のローカルIP通信を取得する。',
    ])
    guide_body = f'''<div class="guide-grid"><div class="panel" data-shape><h3 data-text>通信経路と観測の関係</h3>{bullets(guide_bullets)}</div>
<div class="panel" data-shape><h3 data-text>確認できる汎用指標</h3>
<table class="metrics"><tbody><tr><td>通信相手</td><td>送信元・宛先のIPとポート</td></tr>
<tr><td>通信量・頻度</td><td>ビットレート、パケットレート</td></tr>
<tr><td>パケット数</td><td>区間・累積の活動量</td></tr>
<tr><td>通信の期間</td><td>最初・最後の観測時刻<br>検出・消失イベント</td></tr></tbody></table></div></div>
<div class="warning" data-shape data-text>観測時刻は業務処理の開始・終了時刻そのものではない。<br>消失の判定には設定された無通信時間が関係する。</div>'''
    add('図の読み方', guide_body, guide)

    overview = sections['接続パターン一覧']
    overview_table = overview.split('\n\n')[0]
    add('接続パターン一覧', cells_table(overview_table, 'overview catalog') + '<div class="warning" data-shape data-text>旧7「システム変更前後の影響確認」は、全パターンに共通する比較方法へ。<br>送信・受信の違いと業務用途は、各パターンの適用例として扱う。</div>', overview)

    point_summaries = {
        1: '通信量は保存先の書込み速度や実データ量とは異なる。\n\n通信終了だけでは成功と中断を区別できない。完了・整合性はジョブ結果と照合する。',
        2: '相手を区別できる範囲を取得する。同じIP・ポートへ集約される場合は元の相手を区別できない。\n\n利用者側と依存先側でNICが異なる場合は、両方を取得する。',
        3: 'ループバックを取得対象にする。自動選択時はcapture.include_loopbackの設定を確認する。\n\nUnixドメインソケット・共有メモリは対象外。IP・ポートだけではプロセス名を自動特定できない。',
    }
    mappings = {
        1: '**旧3：バックアップ・ファイル転送**\n\n送信元と保存先の特定の組合せを監視する適用例。',
        2: '**旧1・2・4・5・6**\n\nIoT、ログ収集、DB連携、店舗送信、外部通信を統合。\n\n次ページに適用形態と対応を示す。',
        3: '**旧8：ホスト内のサービス間通信**\n\nWebプロセスとAPIプロセスなど、同一ホスト内の連携を確認する適用例。',
    }
    for i, heading in enumerate(patterns, 1):
        raw = sections[heading]
        subs = split_sections(raw, 3)
        code = re.search(r'```mermaid\n(.*?)```', raw, re.S).group(1)
        image_label = f"<img src='{logo}' width='98' height='30' alt='SubmaLink'/>"
        code = code.replace('<b>SubmaLink</b>', image_label)
        code = code.replace('ループバック：ローカルIP通信', 'ループバック<br/>ローカルIP通信')
        code = code.replace('|"ローカルIP通信を観測"|', '|"ローカルIP通信を<br/>観測"|')
        code = code.replace('|"相手ごとの通信を観測"|', '|"相手ごとの通信を<br/>観測"|')
        code += '\n    style MON fill:#e8f5fc,stroke:#1688b5,stroke-width:2px\n'
        sources.append(code)
        points_cls = ' compact' if i == 3 else ''
        body = f'''<div class="diagram" id="diagram-{i}" data-diagram></div>
<div class="pattern-details"><div class="detail effect" data-shape><h3 data-text>主な監視内容・効果</h3>{bullets(subs['主な監視内容・効果'])}</div>
<div class="detail" data-shape><h3 data-text>既存事例との対応</h3><div data-text>{md(mappings[i])}</div></div>
<div class="detail{points_cls}" data-shape><h3 data-text>適用上の要点</h3><div data-text>{md(point_summaries[i])}</div></div></div>'''
        add(heading, body, raw)
        if i == 2:
            forms = '''<div class="forms"><div class="panel" data-shape><h3 data-text>データ集約</h3><p data-text>複数相手から受信<br>センサーデータ、ログ、拠点報告</p></div>
<div class="panel" data-shape><h3 data-text>データ配信・転送</h3><p data-text>複数相手へ送信<br>複数保存先、外部サービス</p></div>
<div class="panel" data-shape><h3 data-text>サービス間連携</h3><p data-text>複数相手と送受信<br>利用者端末、DB、外部サービス</p></div></div>'''
            mapping = cells_table(subs['既存事例との対応'], 'common mapping')
            add('2. 複数相手との通信の一括監視：適用例と対応', forms + mapping + '<div class="warning" data-shape data-text>定期・常時・必要時の通信では、無通信の意味が異なる。<br>外部通信では未登録通信の観測設定を確認し、宛先の変化は設定やサービス側情報と照合する。</div>', raw)

    # Concise slide wording; speaker notes retain the complete source table.
    common_rows = [
        ('業務処理の成否', '通信の存在だけで成功と判断しない。処理結果やデータの整合性は業務側の記録で確認。'),
        ('制御通信と実データ', '接続維持や確認応答だけが残る場合がある。通信量にはヘッダーや再送も含まれる。'),
        ('通信特性と無通信', '定期・常時・必要時の通信を区別し、通常の送信間隔に合わせて無通信を評価。'),
        ('実行予定との照合', '予定時刻に実行されなかった処理の判定には、別途スケジュールとの照合が必要。'),
        ('正常時・変更前後の比較', '旧7を全パターンへ適用。履歴を保持し、負荷条件を揃えて通信先・通信量・中断期間を比較。'),
        ('専用の内容解析', 'DB処理時間、SQLの成否、DNS応答コードは汎用指標だけでは判定できない。'),
        ('取得範囲と相手の識別', 'NIC・権限・選別条件・名前空間を確認。見えない通信や集約前の相手を推測で補わない。'),
        ('想定外の接続先', '未登録通信の観測設定と通常の宛先変更を確認。自動判定・遮断は前提にしない。'),
        ('取得側の負荷', '取得・解析の処理不足で通信の見え方が変わる場合がある。監視側の状態も確認。'),
    ]
    common_table = '| 確認項目 | 内容 |\n| --- | --- |\n' + '\n'.join('| ' + a + ' | ' + b + ' |' for a, b in common_rows)
    add('共通の確認事項', cells_table(common_table, 'common checks'), sections['共通の確認事項'])
    assert len(slides) == 8 and len(sources) == 3
    # Keep the existing keyboard navigation, but use this deck's title and styling.
    original_html = (SHARED / 'SubmaLink-connection-patterns.html').read_text()
    nav = re.search(r'<script id="navigation">(.*?)</script>', original_html, re.S).group(1)
    document = f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{TITLE}</title><style>{shared.CSS}\n{EXTRA_CSS}</style></head><body>
{''.join(slides)}
<script id="diagram-sources" type="application/json">{json.dumps(sources, ensure_ascii=False)}</script>
<script id="mermaid-vendor">{mermaid_js.read_text()}</script>
<script id="render-mermaid">
window.deckReady=false;
(async()=>{{
mermaid.initialize({{startOnLoad:false,securityLevel:'loose',theme:'base',fontFamily:'Droid Sans Japanese, Droid Sans, sans-serif',themeVariables:{{fontSize:'22px',primaryColor:'#eff5fa',primaryTextColor:'#183448',primaryBorderColor:'#6c90aa',lineColor:'#47677e',edgeLabelBackground:'#ffffff',clusterBkg:'#f5f9fc',clusterBorder:'#9ab6c9'}},flowchart:{{htmlLabels:true,curve:'basis',nodeSpacing:32,rankSpacing:44,padding:18,useMaxWidth:false}}}});
const sources=JSON.parse(document.getElementById('diagram-sources').textContent);
for(let i=0;i<sources.length;i++){{const r=await mermaid.render('general-'+i,sources[i]);document.getElementById('diagram-'+(i+1)).innerHTML=r.svg;}}
await document.fonts.ready;await Promise.all([...document.images].map(i=>i.decode().catch(()=>{{}})));window.deckReady=true;
}})().catch(e=>{{window.deckError=String(e.stack||e)}});
</script><script id="navigation">{nav}</script></body></html>'''
    (work / 'draft.html').write_text(document)
    (work / 'source.json').write_text(json.dumps({'title': TITLE, 'subject': '一般的なネットワーク通信：3パターン・8ページ', 'headings': headings, 'notes': notes, 'diagram_count': 3, 'output_stem': STEM, 'source_sha256': hashlib.sha256(source.read_bytes()).hexdigest(), 'logo_sha256': hashlib.sha256(logo_bytes).hexdigest()}, ensure_ascii=False, indent=2))


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--mermaid-js', type=Path, required=True)
    ap.add_argument('--chrome', default='/root/.cache/puppeteer/chrome/linux-138.0.7204.157/chrome-linux64/chrome')
    ap.add_argument('--node', default='node')
    ap.add_argument('--logo', type=Path, default=ROOT / 'docs/assets/SubmaLink-300w.png')
    ap.add_argument('--work-dir', type=Path)
    args = ap.parse_args()
    work = args.work_dir or Path(tempfile.mkdtemp(prefix='submalink-general-'))
    work.mkdir(parents=True, exist_ok=True)
    make_draft(ROOT / 'docs/general-network-use-cases.md', args.logo.read_bytes(), args.mermaid_js, work)
    subprocess.run([args.node, str(SHARED / 'render.cjs'), str(work), str(HERE), args.chrome], check=True)
    shared.make_pptx(work, HERE / (STEM + '.pptx'), args.logo.read_bytes())
    from pypdf import PdfReader
    assert len(PdfReader(HERE / (STEM + '.pdf')).pages) == 8
    print(f'PASS: 3 patterns and 8 pages in PowerPoint/PDF; build details: {work}')


if __name__ == '__main__':
    main()
