(()=>{{let current=0;const slides=[...document.querySelectorAll('.slide')];function show(){{slides.forEach((s,i)=>s.classList.toggle('active',i===current));const scale=Math.min(innerWidth/1600,innerHeight/900);slides[current].style.transform='scale('+scale+')';slides[current].style.left=((innerWidth-1600*scale)/2)+'px';slides[current].style.top=((innerHeight-900*scale)/2)+'px';}}document.addEventListener('keydown',e=>{{if(e.key==='Escape'){{document.body.classList.remove('presenting');return;}}if(e.key==='p'||e.key==='P'){{document.body.classList.toggle('presenting');show();}}if(['ArrowRight','PageDown',' ','ArrowLeft','PageUp','Home','End'].includes(e.key)&&document.body.classList.contains('presenting')){{e.preventDefault();if(e.key==='Home')current=0;else if(e.key==='End')current=slides.length-1;else current=Math.max(0,Math.min(slides.length-1,current+(['ArrowLeft','PageUp'].includes(e.key)?-1:1)));show();}}}});window.addEventListener('resize',show);}})();
