(() => {
  const root = document.documentElement;
  function syncTheme() {
    let theme = "light";
    try { theme = window.parent.document.documentElement.dataset.theme || "light"; }
    catch { /* Use the default theme when the parent is inaccessible. */ }
    if (root.dataset.theme !== theme) root.dataset.theme = theme;
  }
  syncTheme();
  try {
    new MutationObserver(syncTheme).observe(window.parent.document.documentElement, {
      attributes: true, attributeFilter: ["data-theme"]
    });
  } catch { /* Standalone pages also work without access to the parent. */ }

  for (const frame of document.querySelectorAll("iframe")) {
    const status = frame.previousElementSibling;
    let content;
    function failed() {
      content = undefined;
      frame.classList.remove("is-ready");
      frame.style.height = "0px";
      frame.setAttribute("aria-busy", "false");
      status.hidden = false;
      status.classList.add("is-error");
      status.textContent = "資料を表示できませんでした。「別タブで開く」からご確認ください。";
    }
    function resize() {
      if (!content) return;
      const slide = content.querySelector(".slide");
      const scale = Math.min(1, frame.clientWidth / slide.offsetWidth);
      content.body.style.zoom = String(scale);
      frame.style.height = Math.ceil(content.body.getBoundingClientRect().height) + "px";
    }
    function loaded() {
      try {
        content = frame.contentDocument;
        if (!content?.querySelector(".slide")) return failed();
        // Keep the original files intact. The sandbox disables their presentation
        // shortcuts; each document retains its own CSS and SVG identifiers.
        const style = content.createElement("style");
        style.textContent = "html{overflow:hidden}body{display:flow-root}.slide{transform:none!important;left:auto!important;top:auto!important}";
        content.head.append(style);
        resize();
        frame.classList.add("is-ready");
        frame.setAttribute("aria-busy", "false");
        status.hidden = true;
      } catch { failed(); }
    }
    frame.addEventListener("load", loaded);
    frame.addEventListener("error", failed);
    let width;
    new ResizeObserver(entries => {
      const next = entries[0].contentRect.width;
      if (next !== width) { width = next; resize(); }
    }).observe(frame);
    // A cached document can finish loading before this deferred script runs.
    if (frame.contentDocument?.readyState === "complete" && frame.contentDocument.URL !== "about:blank") loaded();
  }
})();
