// Render Mermaid, validate actual layout, and export an offline HTML/PDF deck.
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { spawn } = require('node:child_process');
const { once } = require('node:events');
const assert = require('node:assert/strict');
const WebSocket = require('../../../fe/node_modules/ws');
const [work, out, chromePath] = process.argv.slice(2);
const source = JSON.parse(fs.readFileSync(path.join(work, 'source.json'), 'utf8'));
const pageCount = source.headings.length;
const diagramCount = source.diagram_count ?? 9;
const outputStem = source.output_stem || 'SubmaLink-connection-patterns';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

(async () => {
  const server = http.createServer((req, res) => {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.end(fs.readFileSync(path.join(work, 'draft.html')));
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const chrome = spawn(chromePath, ['--headless', '--no-sandbox', '--disable-dev-shm-usage', '--remote-debugging-port=0', '--user-data-dir=' + path.join(work, 'chrome'), 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
  let log = '', socket;
  chrome.stderr.on('data', b => { log += b; });
  try {
    for (let i = 0; i < 200 && !log.includes('DevTools listening'); i++) await sleep(50);
    const port = log.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1];
    assert.ok(port, log);
    const address = 'http://127.0.0.1:' + server.address().port;
    const tab = await new Promise((resolve, reject) => {
      const req = http.request(`http://127.0.0.1:${port}/json/new?${address}`, { method: 'PUT' }, res => {
        let body = '';
        res.on('data', b => { body += b; });
        res.on('end', () => { try { resolve(JSON.parse(body)); } catch (e) { reject(e); } });
      });
      req.on('error', reject); req.end();
    });
    socket = new WebSocket(tab.webSocketDebuggerUrl);
    await once(socket, 'open');
    let seq = 0;
    const pending = new Map();
    socket.on('message', b => {
      const m = JSON.parse(b);
      if (m.id) {
        const p = pending.get(m.id);
        pending.delete(m.id);
        m.error ? p.reject(m.error) : p.resolve(m.result);
      }
    });
    const call = (method, params = {}) => new Promise((resolve, reject) => {
      const id = ++seq;
      pending.set(id, { resolve, reject });
      socket.send(JSON.stringify({ id, method, params }));
    });
    const evaluate = async expression => {
      const r = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
      assert.ok(!r.exceptionDetails, JSON.stringify(r.exceptionDetails));
      return r.result.value;
    };
    await call('Emulation.setDeviceMetricsOverride', { width: 1600, height: 900, deviceScaleFactor: 2, mobile: false });
    for (let i = 0; i < 400; i++) {
      const state = await evaluate('({ready:window.deckReady,error:window.deckError})');
      assert.ok(!state.error, state.error);
      if (state.ready) break;
      await sleep(50);
    }
    assert.equal(await evaluate('window.deckReady'), true);
    // Tables use native text and row/cell fills when exported to PowerPoint.
    await evaluate(`document.querySelectorAll('th,td').forEach(e=>{e.setAttribute('data-text','');e.setAttribute('data-shape','')})`);
    const validation = await evaluate(`(()=>{
      const errors=[];
      if(document.querySelectorAll('.slide').length!==${pageCount})errors.push('page count');
      if(document.querySelectorAll('[data-diagram]>svg').length!==${diagramCount})errors.push('diagram count');
      for(const e of document.querySelectorAll('.detail,.panel,.warning,.overview,.common')){
        if(e.scrollHeight>e.clientHeight+2)errors.push('vertical overflow: '+e.closest('.slide').id+' '+e.className);
      }
      for(const e of document.querySelectorAll('.detail,.diagram,.overview,.common,.warning')){
        const p=e.closest('.slide').getBoundingClientRect(),r=e.getBoundingClientRect();
        if(r.bottom>p.top+819||r.right>p.right-45)errors.push('page boundary: '+e.closest('.slide').id+' '+e.className);
      }
      for(const slide of document.querySelectorAll('.slide')){
        const banner=slide.querySelector('.warning');
        if(!banner)continue;
        for(const content of slide.querySelectorAll('.mapping,.catalog,.guide-grid')){
          if(content.getBoundingClientRect().bottom>banner.getBoundingClientRect().top-4)
            errors.push('content overlaps note: '+slide.id+' '+content.className);
        }
      }
      if(/\\bstm\\b/i.test(document.body.innerText))errors.push('old product name visible');
      for(const i of document.images)if(!i.complete||!i.naturalWidth)errors.push('missing logo');
      const logos=[...document.querySelectorAll('[data-diagram] img')];
      if(logos.length!==${diagramCount})errors.push('diagram logo count: '+logos.length);
      for(const image of logos){
        const a=image.getBoundingClientRect();
        for(const node of image.closest('svg').querySelectorAll('.node rect')){
          // A subgraph may itself be a node; its frame intentionally contains the logo.
          if(node.closest('.cluster')||node.closest('g.node')?.contains(image))continue;
          const b=node.getBoundingClientRect();
          if(Math.min(a.right,b.right)-Math.max(a.left,b.left)>1&&Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top)>1)
            errors.push('logo overlaps node: '+image.closest('.slide').id+' '+JSON.stringify({image:[a.left,a.top,a.right,a.bottom],node:[b.left,b.top,b.right,b.bottom],element:node.outerHTML.slice(0,110)}));
        }
      }
      return {errors,slides:${pageCount},diagrams:${diagramCount},diagramLogos:logos.length};
    })()`);
    fs.writeFileSync(path.join(work, 'validation.json'), JSON.stringify(validation, null, 2));
    assert.deepEqual(validation.errors, [], JSON.stringify(validation));
    const layout = { pages: [] };
    for (let n = 1; n <= pageCount; n++) {
      const page = await evaluate(`(()=>{
        const s=document.getElementById('slide-${n}'),base=s.getBoundingClientRect();
        const rect=e=>{const r=e.getBoundingClientRect();return {x:r.x-base.x,y:r.y-base.y,w:r.width,h:r.height}};
        const color=v=>{const a=v.match(/[\\d.]+/g);return !a||a[3]==='0'?null:'#'+a.slice(0,3).map(n=>Math.round(+n).toString(16).padStart(2,'0')).join('')};
        const shapes=[...s.querySelectorAll('[data-shape]')].map(e=>{const c=getComputedStyle(e);return {...rect(e),fill:color(c.backgroundColor),border:parseFloat(c.borderTopWidth)?color(c.borderTopColor):null,radius:parseFloat(c.borderRadius)}});
        const images=[...s.querySelectorAll('img')].filter(e=>!e.closest('[data-diagram]')).map(rect);
        const text=[];
        for(const block of s.querySelectorAll('[data-text]')){
          const walk=document.createTreeWalker(block,NodeFilter.SHOW_TEXT);
          let node;
          while(node=walk.nextNode()){
            if(node.parentElement.closest('[data-text]')!==block)continue;
            const c=getComputedStyle(node.parentElement);let line=null;
            for(let i=0;i<node.textContent.length;i++){
              const range=document.createRange();range.setStart(node,i);range.setEnd(node,i+1);
              const r=range.getBoundingClientRect();if(!r.width||!r.height)continue;
              if(!line||Math.abs(line.y-(r.y-base.y))>2){line={text:'',x:r.x-base.x,y:r.y-base.y,w:0,h:r.height,size:parseFloat(c.fontSize),bold:+c.fontWeight>=600,color:color(c.color)};text.push(line)}
              line.text+=node.textContent[i];line.w=r.right-base.x-line.x;
            }
          }
        }
        return {shapes,images,text,diagrams:[...s.querySelectorAll('[data-diagram]')].map(e=>({...rect(e),id:e.id})),clip:{x:base.x,y:base.y,width:base.width,height:base.height}};
      })()`);
      for (const d of page.diagrams) {
        const shot = await call('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true, clip: { x: d.x + page.clip.x, y: d.y + page.clip.y, width: d.w, height: d.h, scale: 1 } });
        d.file = d.id + '.png';
        fs.writeFileSync(path.join(work, d.file), Buffer.from(shot.data, 'base64'));
      }
      const shot = await call('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true, clip: { ...page.clip, scale: 1 } });
      fs.writeFileSync(path.join(work, 'slide-' + String(n).padStart(2, '0') + '.png'), Buffer.from(shot.data, 'base64'));
      layout.pages.push(page);
    }
    fs.writeFileSync(path.join(work, 'layout.json'), JSON.stringify(layout));
    const pdf = await call('Page.printToPDF', { printBackground: true, preferCSSPageSize: true, displayHeaderFooter: false, marginTop: 0, marginBottom: 0, marginLeft: 0, marginRight: 0 });
    fs.writeFileSync(path.join(out, outputStem + '.pdf'), Buffer.from(pdf.data, 'base64'));
    const frozen = await evaluate(`(()=>{document.getElementById('mermaid-vendor').remove();document.getElementById('render-mermaid').remove();return '<!doctype html>\\n'+document.documentElement.outerHTML})()`);
    fs.writeFileSync(path.join(out, outputStem + '.html'), frozen);
    console.log(`PASS: rendered ${pageCount} pages, ${diagramCount} diagrams and ${diagramCount} diagram logos; layout checks passed.`);
  } finally {
    socket?.close(); chrome.kill('SIGTERM'); server.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
# stmの活用例：接続パターンと監視効果

ネットワークスイッチ、タップ、ポートミラーリングを利用して通信を取得し、stmで監視する接続例を示す。VLAN、トランクポート、ボンディング、VXLANを利用する構成も含む。

## 図の読み方

- 実線の矢印は本線の通信、破線の矢印は監視用コピーを示す。
- 図の矢印は主な配信方向を示す。双方向通信の監視では、必要な両方向を取得する。
- 各図の「stm」枠は1台の監視ホストを表し、枠内のNICはそのホストの取得口を表す。
- タップは本線上に設置するネットワークタップを指す。タップの監視出力やスイッチのミラー出力をstmへ接続する。
- 複数の観測点を比較する場合は、観測点ごとに別NICへ入力して識別する。

ここでの「比較」は、観測点ごとのメトリクスやイベントを照合する運用を指す。パケット単位の自動突合や厳密な片道遅延測定は前提にしない。

図はMermaidのコードブロックで記述している。図としての表示には、Mermaidに対応したMarkdownビューアーが必要となる。

## 接続パターン一覧

| No. | 接続パターン | 主な取得位置・方法 | 期待できる効果 |
| --- | --- | --- | --- |
| 1 | ポートミラーリングによる基本監視 | スイッチの対象ポートからコピーを取得 | 通信の有無、ビットレート、プロトコル別の異常を継続監視 |
| 2 | ネットワークタップによる監視 | 本線に設置したタップから取得 | スイッチのミラー設定に依存せず、対象リンクの通信を観測 |
| 3 | スイッチ前後比較 | スイッチの入力側・出力側を別々に取得 | 入力時点の異常と、通過後に現れる異常を切り分け |
| 4 | 分岐後比較 | 分岐前と各分岐先で取得 | 全経路に共通する異常と、特定経路だけの異常を切り分け |
| 5 | VLAN／トランクポートの一括監視 | トランクの通信をVLANタグ保持でミラー | 複数VLANの通信量・異常を1つの取得口で整理 |
| 6 | 複数スイッチ間の区間比較 | 中継区間の両端で取得 | 中継区間を含む下流側で異常が発生するかを確認 |
| 7 | ボンディング／LAGの負荷分散確認 | 束ねた各物理リンクで取得 | 通信の偏りや、特定リンクに関連する異常を確認 |
| 8 | 冗長経路・ボンディング切替の確認 | 主系と待機系を別々に取得 | 切替時の通信停止・復帰状況や片系の品質低下を確認 |
| 9 | VXLAN区間を挟んだ比較 | カプセル化前とカプセル解除後で取得 | VXLAN網を含む区間の前後で通信品質を比較 |

## 1. ポートミラーリングによる基本監視

```mermaid
flowchart LR
    SRC["送信機"] --> SW["ネットワークスイッチ"]
    SW --> DST["受信機"]
```

**効果：** 主系の通信停止から待機系での通信再開までの状況を確認し、切替時の中断や復帰後の異常を調べられる。

**接続上の要点：** 図はactive-backupの例であり、待機系の実線は切替後の配信経路を示す。平常時に待機系で監視対象ストリームが見えないこと自体は異常ではない。

主系・待機系ごとの監視だけでなく、受信側の観測を追加すると、経路の切替後に実際に受信側へ通信が届いたかも確認できる。両系へ常時配信するA系／B系の構成では、それぞれの品質を並行して比較する。

## 9. VXLAN区間を挟んだ比較

```mermaid
flowchart LR
    SRC["送信機"] --> T1["カプセル化前のタップ"]
    T1 --> V1["VTEP A：カプセル化"]
    V1 --> NET["VXLAN網"]
    NET --> V2["VTEP B：カプセル解除"]
    V2 --> T2["カプセル解除後のタップ"]
    T2 --> DST["受信機"]
    T1 -.->|"通常通信のコピー"| N1
    T2 -.->|"通常通信のコピー"| N2
    subgraph STM ["stm"]
        N1["NIC 1：VXLAN区間の前"]
        N2["NIC 2：VXLAN区間の後"]
    end
```

**効果：** VXLAN網を含む区間の前後で、通常のRTPなどの通信品質を比較できる。

**接続上の要点：** VTEPはVXLANのカプセル化／解除を行う終端を指す。現行stmの共通scope出力は`vxlan: null`であり、VNIと内側フローを対応付ける直接監視は追加対応が必要となる。この図では、VTEPの外側にある通常通信を取得する。

前後の差だけでは、VTEP自体とVXLAN網内の個別機器のどこで問題が発生したかまでは特定できない。観測点が遠隔にある場合の扱いはパターン6と同様となる。

## 共通の確認事項

| 確認項目 | 内容 |
| --- | --- |
| 観測点の識別 | 比較する前後・経路は別NICに入力し、監視対象にもNIC条件を指定して区別する。 |
| 比較する通信 | 同一ストリームかをプロトコル、送受信先、VLAN、観測点の対応から確認する。変換装置がある場合は前後の通信の対応も整理する。 |
| 取得方向 | 必要な方向を取得する。SRTなどでは戻り方向の制御通信も監視目的に応じて含める。 |
| 監視コピーの欠落 | ミラー出力やタップの集約出力の帯域、NIC、取得・解析処理の負荷を確認する。本線が正常でも監視コピーだけが欠落する場合がある。 |
| VLANタグ | スイッチのミラー設定と取得環境でタグが保持されるかを確認する。 |
| 物理リンクの区別 | ボンディング／LAGの各リンクを調べる場合は、物理リンク別に取得する。 |
| 時刻と測定粒度 | 複数ホストの記録を比較する場合は時刻同期を行う。停止・復帰の比較精度は取得条件とメトリクス・イベントの記録粒度に依存する。 |
| 表示する品質指標 | RTPのシーケンス欠落など、対象プロトコルで取得・評価できる指標を利用する。全プロトコルに同一の指標を適用しない。 |

